function config(){const low=+$('low').value,high=+$('high').value,ms=+$('speed').value,gain=+$('gain').value/100;if(!Number.isFinite(low)||!Number.isFinite(high)||low<18000||high>23000||high-low<750)throw Error('ใช้ย่านกว้างอย่างน้อย 750 Hz ระหว่าง 18,000–23,000 Hz');if(low<20000&&!$('audible').checked)throw Error('ย่านต่ำกว่า 20 kHz อาจได้ยิน กรุณายืนยันก่อน');if(ctx&&high>ctx.sampleRate/2-200)throw Error(`sample rate เครื่องนี้รองรับถึง ${Math.floor(ctx.sampleRate/2-200)} Hz ในแอพนี้ ลดค่าสูงสุดก่อน`);return {low,high,ms,gain};}
