function configure(){if(!receiver)return;const c=config();receiver.port.postMessage({config:true,...c});}
function setListen(on){listening=on;receiver?.port.postMessage({muted:!on||tx});$('listen').textContent=on?'✓ กำลังรับ / ตอบ ACK':'เปิดรับ / ตอบ ACK';}
