async function sha(bytes){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');}
function statsUI(s,start){const elapsed=(performance.now()-start)/1000;info('packets',`${s.success} / ${s.attempted}`);info('retries',s.retries);$('goodput').innerHTML=(s.bytes*8/Math.max(.001,elapsed)).toFixed(1)+'<em> bit/s</em>';}
async function run(kind,data=null,isText=false){if($('role').value!=='tx')throw Error('ตั้งเครื่องนี้เป็นผู้ส่งก่อน');if(busy)throw Error('มีการทดลองกำลังทำงาน');const c=config();configure();setListen(true);lock(true);const mine=token,session=crypto.getRandomValues(new Uint16Array(1))[0],st=performance.now(),s={attempted:0,success:0,retries:0,bytes:0,transmissions:0};badFrames=0;let complete=false,error=null;try{if(kind==='benchmark'){for(let i=0;i<3;i++){const payload=crypto.getRandomValues(new Uint8Array(32));s.attempted++;info('transferStatus',`กำลังทดสอบ ${i+1} / 3 · รอ ACK ผ่านเสียง`);const ok=await acknowledged(1,session,i,payload,s,mine);if(ok){s.success++;s.bytes+=payload.length;}statsUI(s,st);if(!ok)info('transferStatus','ไม่ได้ ACK · ตรวจย่าน ความเร็ว ระยะและระดับเสียงทั้งสองเครื่อง');}complete=s.success===3;}else{const meta=enc.encode(JSON.stringify({size:data.length,hash:await sha(data)}));s.attempted++;if(!await acknowledged(3,session,0,meta,s,mine))throw Error('ไม่ได้ ACK เริ่มไฟล์ ตรวจการรับอีกเครื่อง');s.success++;for(let i=0;i<Math.ceil(data.length/32);i++){s.attempted++;info('transferStatus',`ส่งข้อมูล ${Math.min(i*32,data.length)} / ${data.length} bytes`);const part=data.slice(i*32,(i+1)*32);if(!await acknowledged(4,session,i,part,s,mine))throw Error('ไม่ได้ ACK ของข้อมูล หยุดรอบนี้ กรุณาทดลองใหม่');s.success++;s.bytes+=part.length;statsUI(s,st);}s.attempted++;if(!await acknowledged(5,session,0,new Uint8Array([isText?1:0]),s,mine))throw Error('ยังไม่ได้ยืนยัน SHA-256 จากผู้รับ');s.success++;complete=true;}info('transferStatus',complete?'สำเร็จ · บันทึก goodput แล้ว ลองความเร็วอื่นโดยตั้งทั้งสองเครื่องให้ตรงกัน':'จบรอบ แต่รับยืนยันไม่ครบ · บันทึกผลตามจริงแล้ว');}catch(e){error=e.message;info('transferStatus',e.message);}finally{if(ackWait?.session===session){clearTimeout(ackWait.timer);ackWait.resolve(false);ackWait=null;}const elapsed=(performance.now()-st)/1000;if(kind!=='benchmark'&&!complete)s.bytes=0;statsUI(s,st);save({kind,range:[c.low,c.high],gain:c.gain,rawBitrate:2000/c.ms,...s,goodputBps:s.bytes*8/elapsed,elapsedSeconds:elapsed,crcFailures:badFrames,complete,error,goodputDefinition:kind==='benchmark'?'unique CRC-valid payload bytes acoustically ACKed / full elapsed time including retries':'whole file bytes after final SHA-256 ACK / full elapsed time; zero if not confirmed'});if(mine===token)lock(false);}}
function bind(id,fn){$(id).addEventListener('click',async()=>{try{await fn();}catch(e){toast(e.message);}});}
bind('start',start);bind('stop',stop);bind('capture',async()=>{await start();beginCapture();});bind('finish',finishCapture);bind('sweep',async()=>{await start();await sweep();});bind('listen',async()=>{await start();configure();setListen(true);info('transferStatus','พร้อมรับและตอบ ACK · ตั้งย่านและความเร็วให้ตรงกับผู้ส่ง');});bind('bench',async()=>{await start();await run('benchmark');});bind('sendText',async()=>{const b=enc.encode($('message').value);if(!b.length)throw Error('พิมพ์ข้อความก่อน');await start();await run('text',b,true);});$('file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>4096)throw Error('รุ่นทดลองรองรับไฟล์ไม่เกิน 4 KB');if(!f.size)throw Error('ไฟล์ว่าง');await start();await run('file',new Uint8Array(await f.arrayBuffer()));}catch(e){toast(e.message);}finally{e.target.value='';}});
bind('useBand',()=>{if(recommendation){$('low').value=recommendation[0];$('high').value=recommendation[1];configure();toast('ตั้งย่านแล้ว ตั้งอีกเครื่องให้ตรงกันด้วย');}});$('gain').oninput=()=>info('gainValue',$('gain').value+'%');for(const id of ['low','high','speed','audible'])$(id).addEventListener('change',()=>{try{config();configure();if(id!=='speed'){baseline=null;held=null;recommendation=null;$('useBand').disabled=true;info('band','ต้องวัดย่านใหม่');}}catch(e){setListen(false);toast(e.message);}});$('role').onchange=()=>setListen($('role').value==='rx');$('device').onchange=()=>{try{localStorage.setItem('sonicbeam-device',$('device').value);}catch{}};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const t of document.querySelectorAll('.tab'))t.classList.toggle('active',t.id===b.dataset.tab);for(const n of document.querySelectorAll('[data-tab]'))n.classList.toggle('active',n===b);if(b.dataset.tab==='scan')renderScan();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000);}
bind('export',()=>download(new Blob([JSON.stringify({app:'SonicBeam Lab',version:1,exportedAt:new Date().toISOString(),sessions:history},null,2)],{type:'application/json'}),'sonicbeam-results.json'));
$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('ไฟล์ผลใหญ่เกิน 2 MB');const d=JSON.parse(await f.text());if(d.app!=='SonicBeam Lab'||!Array.isArray(d.sessions)||d.sessions.some(r=>!r||typeof r!=='object'||!['spectrum','benchmark','file','text','frequency-scan'].includes(r.kind)||!Array.isArray(r.range)||r.range.length!==2||!r.range.every(Number.isFinite)))throw Error('รูปแบบผลไม่ถูกต้อง');const ids=new Set(history.map(r=>r.id));for(const r of d.sessions)if(!ids.has(r.id)){history.push(r);ids.add(r.id);}history=history.slice(-100);localStorage.setItem('sonicbeam-history',JSON.stringify(history));renderHistory();toast('นำเข้าผลแล้ว');}catch(e){toast(e.message);}finally{e.target.value='';}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started){stop();toast('หยุดเสียงเมื่อออกจากหน้า เปิดเสียงอีกครั้งเมื่อกลับมา');}});window.addEventListener('resize',()=>{paint(+$('low').value,+$('high').value);renderScan();});renderHistory();paint(20000,22000);

// Frequency survey: control-band negotiation -> timed measurement lease -> return.
function setBand(c){$('low').value=c.low;$('high').value=c.high;$('speed').value=c.ms;configure();}
function validScanCommand(q){return q&&Number.isFinite(q.low)&&Number.isFinite(q.high)&&q.low>=($('audible').checked?18000:20000)&&q.high<=Math.min(23000,ctx.sampleRate/2-200)&&q.high-q.low>=750&&[10,20,40,80].includes(q.ms)&&Number.isInteger(q.lease)&&q.lease>=10000&&q.lease<=900000;}
function switchScanReceiver(p,q){const base=config();rxScan={session:p.session,base,timer:null,received:0};lock(true);setBand(q);setListen(true);setQuickState('running','กำลังรับการทดสอบ',`${(q.low/1000).toFixed(2)}–${(q.high/1000).toFixed(2)} kHz`);info('scanStatus',`รับคำสั่งผ่านเสียง → กำลังทดสอบ ${(q.low/1000).toFixed(2)}–${(q.high/1000).toFixed(2)} kHz · จะกลับย่านควบคุมเองหากลิงก์ขาด`);info('transferStatus','กำลังรับชุดกวาดย่านอัตโนมัติ');rxScan.timer=setTimeout(restoreScanReceiver,q.lease);}
function restoreScanReceiver(){if(!rxScan)return;const r=rxScan;rxScan=null;clearTimeout(r.timer);if(started){setBand(r.base);lock(false);setListen(true);setQuickState('ready','พร้อมรับช่วงถัดไป','ไม่ต้องกดอะไรเพิ่ม รอเครื่องส่งทดสอบต่อ');info('scanStatus','กลับย่านควบคุมแล้ว รอช่วงถัดไปจากผู้ส่ง');}}
function scanBands(low,high,width,step){const bands=[];for(let a=low;a+width<=high;a+=step)bands.push({low:a,high:a+width,measurements:[]});if(bands.length&&bands.at(-1).high<high)bands.push({low:high-width,high,measurements:[]});return bands;}
function scanSummary(b){const a=b.measurements||[];if(!a.length)return null;const values=a.map(v=>v.goodputBps);return {mean:values.reduce((s,v)=>s+v,0)/values.length,min:Math.min(...values),max:Math.max(...values),n:a.length,success:a.reduce((s,v)=>s+v.success,0),attempted:a.reduce((s,v)=>s+v.attempted,0)};}
function usableScan(r){return r&&r.kind==='frequency-scan'&&Array.isArray(r.bands)&&r.bands.length<=30&&r.bands.every(b=>Number.isFinite(b.low)&&Number.isFinite(b.high)&&b.high>b.low&&Array.isArray(b.measurements)&&b.measurements.length<=10&&b.measurements.every(m=>Number.isFinite(m.goodputBps)&&m.goodputBps>=0));}
async function waitLease(until,mine){while(performance.now()<until){if(mine!==token)throw Error('หยุดแล้ว');info('scanStatus',`ย่านนี้ตอบกลับไม่ครบ · รอทั้งสองเครื่องกลับย่านควบคุมอีก ${Math.ceil((until-performance.now())/1000)} วินาที`);await delay(Math.min(500,until-performance.now()));}}
async function scanAll(){if($('role').value!=='tx')throw Error('ให้เครื่องนี้เป็นผู้ส่ง และอีกเครื่องเปิดรับ');if(busy)throw Error('มีการทดลองกำลังทำงาน');const base=config(),requested=+$('scanRange').value,width=+$('scanWidth').value,step=+$('scanStep').value,repeats=+$('scanRepeats').value;if(requested<20000&&!$('audible').checked)throw Error('เลือกยอมรับย่านที่อาจได้ยินในหน้าสำรวจก่อน ทั้งสองเครื่อง');configure();setListen(true);lock(true);const mine=token,session=crypto.getRandomValues(new Uint16Array(1))[0],controlStats={retries:0,transmissions:0};let failure=null;scanResult=null;renderScan();try{info('scanStatus','ตรวจช่องควบคุมและ sample rate ของอีกเครื่องผ่านเสียง…');if(!await acknowledged(8,session,0,new Uint8Array(),controlStats,mine))throw Error('ช่องควบคุมยังไม่ได้ ACK: ทดสอบย่านปัจจุบันให้ส่งไป–กลับได้ก่อน แล้วเริ่มกวาดใหม่');if(!peerCapabilities||!Number.isFinite(peerCapabilities.sampleRate))throw Error('อีกเครื่องต้องใช้แอพรุ่นที่รองรับการกวาดย่าน');const upper=Math.floor(Math.min(23000,ctx.sampleRate/2-200,peerCapabilities.sampleRate/2-200)/250)*250;const lower=Math.max(requested,peerCapabilities.minHz);if(lower!==requested)throw Error('อีกเครื่องยังไม่ยอมรับย่านต่ำกว่า 20 kHz กรุณาตั้งให้ตรงกัน');const bands=scanBands(lower,upper,width,step);if(!bands.length)throw Error('sample rate ของคู่เครื่องไม่เหลือช่วงกว้างพอสำหรับการทดสอบ');scanResult={...metadata(),kind:'frequency-scan',range:[lower,upper],controlRange:[base.low,base.high],rawBitrate:2000/base.ms,bandwidthHz:width,stepHz:step,repeats,peerSampleRate:peerCapabilities.sampleRate,bands,complete:false,controlStats};renderScan();
 // Worst-case lease includes two payload packets per round, all retries, and finish handshake.
 const ackTimeout=(24+14*4)*base.ms+1800,payloadDuration=(24+39*4)*base.ms+220,endDuration=(24+7*4)*base.ms+220;
 const lease=Math.ceil((repeats*2*3*(payloadDuration+ackTimeout+500)+3*(endDuration+ackTimeout+500)+6000)/1000)*1000;
 info('scanStatus',`พบ ${bands.length} ช่วง · ${2000/base.ms} bit/s ดิบ · หากหลายช่วงไม่ผ่าน อาจใช้เวลาสูงสุดประมาณ ${Math.ceil(bands.length*lease/60000)} นาที`);
 for(let i=0;i<bands.length;i++){if(mine!==token)throw Error('หยุดแล้ว');const b=bands[i];setBand(base);info('scanStatus',`นัดเปลี่ยนช่วง ${i+1}/${bands.length}: ${(b.low/1000).toFixed(2)}–${(b.high/1000).toFixed(2)} kHz`);const command=enc.encode(JSON.stringify({low:b.low,high:b.high,ms:base.ms,lease}));const commandStart=performance.now();if(!await acknowledged(6,session,i,command,controlStats,mine)){await waitLease(commandStart+lease+4000,mine);throw Error('ไม่ได้ยืนยันการเปลี่ยนย่าน จบชุดนี้โดยไม่ใส่ค่า 0 ให้ช่วงที่ยังไม่ได้วัด');}setBand({low:b.low,high:b.high,ms:base.ms});const expires=performance.now()+lease+1500;
 for(let round=0;round<repeats;round++){const st=performance.now(),stats={attempted:0,success:0,retries:0,transmissions:0,bytes:0};for(let j=0;j<2;j++){info('scanStatus',`ช่วง ${i+1}/${bands.length} · ${(b.low/1000).toFixed(2)}–${(b.high/1000).toFixed(2)} kHz · รอบ ${round+1}/${repeats} · แพ็กเก็ต ${j+1}/2`);stats.attempted++;const payload=crypto.getRandomValues(new Uint8Array(32));if(await acknowledged(1,session,round*2+j,payload,stats,mine)){stats.success++;stats.bytes+=32;}}const elapsed=(performance.now()-st)/1000;b.measurements.push({...stats,elapsedSeconds:elapsed,goodputBps:stats.bytes*8/elapsed});renderScan();}
 const returned=await acknowledged(7,session,i,new Uint8Array(),controlStats,mine);if(!returned)await waitLease(expires,mine);setBand(base);await delay(500);
 }await acknowledged(8,session,255,new Uint8Array([1]),controlStats,mine);scanResult.complete=true;info('scanStatus','กวาดครบแล้ว · ทั้งสองเครื่องกลับย่านควบคุม · เปลี่ยน gain หรือความเร็วแล้วทดสอบซ้ำเพื่อเปรียบเทียบ');}catch(e){failure=e.message;info('scanStatus',e.message);if(!scanResult)toast(e.message);}finally{if(ackWait?.session===session){clearTimeout(ackWait.timer);ackWait.resolve(false);ackWait=null;}if(scanResult){scanResult.error=failure;save(scanResult);renderScan();}if(mine===token&&started){setBand(base);lock(false);setListen(true);}}return {complete:!!scanResult?.complete,error:failure};}
function renderScan(){refreshQuickProgress();const canvas=$('goodputChart'),w=canvas.clientWidth,h=canvas.clientHeight;if(!w)return;const dpr=Math.min(2,devicePixelRatio||1);canvas.width=w*dpr;canvas.height=h*dpr;const g=canvas.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,w,h);const l=49,r=w-20,t=32,b=h-47,valid=usableScan(scanResult),bands=valid?scanResult.bands:[],summary=bands.map(scanSummary),lo=valid?bands[0].low:20000,hi=valid?bands.at(-1).high:23000,max=Math.max(10,Math.ceil(Math.max(0,...summary.map(s=>s?.max||0))*1.15/5)*5);const x=f=>l+(f-lo)/(hi-lo)*(r-l),y=v=>b-v/max*(b-t);g.font='10px system-ui';g.fillStyle='#9aafaf';g.fillText('Goodput (bit/s)',l,t-14);for(let i=0;i<=4;i++){const yy=y(max*i/4);g.strokeStyle='#29383e';g.beginPath();g.moveTo(l,yy);g.lineTo(r,yy);g.stroke();g.fillStyle='#8ba1a8';g.fillText((max*i/4).toFixed(1),5,yy+3);}for(let i=0;i<=4;i++){const f=lo+(hi-lo)*i/4;g.fillStyle='#8ba1a8';g.textAlign='center';g.fillText((f/1000).toFixed(2),x(f),b+19);}g.fillStyle='#a8bcb9';g.fillText('ความถี่กลางของช่วง (kHz)',(l+r)/2,h-6);g.textAlign='start';let prev=null;bands.forEach((band,i)=>{const ss=summary[i],xx=x((band.low+band.high)/2);if(!ss){g.strokeStyle='#6e8084';g.beginPath();g.arc(xx,b-2,3.5,0,Math.PI*2);g.stroke();prev=null;return;}const yy=y(ss.mean);if(prev){g.strokeStyle='#a3eed8';g.lineWidth=2;g.beginPath();g.moveTo(...prev);g.lineTo(xx,yy);g.stroke();}prev=[xx,yy];if(ss.n>1){g.strokeStyle='#eccc84';g.lineWidth=1.4;g.beginPath();g.moveTo(xx,y(ss.min));g.lineTo(xx,y(ss.max));g.moveTo(xx-4,y(ss.min));g.lineTo(xx+4,y(ss.min));g.moveTo(xx-4,y(ss.max));g.lineTo(xx+4,y(ss.max));g.stroke();}g.fillStyle=ss.mean===0?'#efac9b':'#a3eed8';g.beginPath();g.arc(xx,yy,4,0,Math.PI*2);g.fill();});if(!bands.length){g.fillStyle='#94aaa8';g.textAlign='center';g.fillText('กราฟจะขึ้นเมื่อเริ่มทดสอบ',(l+r)/2,(t+b)/2);g.textAlign='start';}const table=$('scanTable');table.replaceChildren();for(let i=0;i<bands.length;i++){const band=bands[i],ss=summary[i],tr=document.createElement('tr');for(const v of [`${(band.low/1000).toFixed(2)}–${(band.high/1000).toFixed(2)}`,ss?ss.mean.toFixed(2):'ยังไม่ทดสอบ',ss?`${ss.min.toFixed(2)}–${ss.max.toFixed(2)}`:'—',ss?String(ss.n):'—',ss?`${ss.success}/${ss.attempted}`:'—']){const td=document.createElement('td');td.textContent=v;tr.append(td);}table.append(tr);}const ranked=bands.map((band,i)=>({band,s:summary[i]})).filter(v=>v.s&&v.s.mean>0).sort((a,b)=>b.s.mean-a.s.mean);info('scanBest',ranked.length?`ย่านที่ทำได้ดีที่สุด: ${(ranked[0].band.low/1000).toFixed(2)}–${(ranked[0].band.high/1000).toFixed(2)} kHz · ${ranked[0].s.mean.toFixed(2)} bit/s`:bands.length?'ยังไม่มีช่วงที่ยืนยัน payload ผ่าน ACK':'ยังไม่มีย่านที่ยืนยันผล');}
bind('scanStart',async()=>{await start();await scanAll();});bind('scanShowLatest',()=>{const latest=[...history].reverse().find(usableScan);if(!latest)throw Error('ยังไม่มีชุดกวาดความถี่ที่บันทึกไว้');scanResult=latest;info('scanStatus',`ผลที่บันทึก: ${new Date(latest.at).toLocaleString('th-TH')} · ${latest.device} · ${latest.complete?'ครบทุกช่วง':'บางช่วง / ถูกหยุด'}`);renderScan();});$('goodputChart').addEventListener('click',e=>{if(!usableScan(scanResult))return;const rect=$('goodputChart').getBoundingClientRect(),l=49,r=rect.width-20,lo=scanResult.bands[0].low,hi=scanResult.bands.at(-1).high,f=lo+(e.clientX-rect.left-l)/(r-l)*(hi-lo);const band=[...scanResult.bands].sort((a,b)=>Math.abs((a.low+a.high)/2-f)-Math.abs((b.low+b.high)/2-f))[0],ss=scanSummary(band);info('scanDetail',`${(band.low/1000).toFixed(2)}–${(band.high/1000).toFixed(2)} kHz · ${ss?`เฉลี่ย ${ss.mean.toFixed(2)} bit/s · ต่ำสุด ${ss.min.toFixed(2)} / สูงสุด ${ss.max.toFixed(2)} · ${ss.n} รอบ · ACK ${ss.success}/${ss.attempted}`:'ยังไม่ทดสอบ'}`);});


// One primary action per role; shared control defaults work at 44.1 and 48 kHz.
function setQuickState(state,title,hint){quickState=state;$('quickHome').dataset.state=state;$('quickTitle').textContent=title;$('quickHint').textContent=hint;syncQuickButtons();}
function syncQuickButtons(){const role=$('role').value,blocked=busy||quickLaunching,receiving=role==='rx'&&started&&listening;$('quickRx').disabled=blocked;$('quickTx').disabled=blocked;$('quickStart').disabled=blocked||receiving;$('quickButtonText').textContent=quickLaunching?'กำลังเปิดไมโครโฟน…':blocked?(role==='rx'?'กำลังรับ…':'กำลังทดสอบ…'):receiving?'กำลังรับ · ไม่ต้องกดเพิ่ม':quickState==='error'?'ลองอีกครั้ง':role==='rx'?'เริ่มรับ':quickState==='complete'?'ทดสอบอีกครั้ง':'เริ่มทดสอบ';}
function renderQuickRole(){const role=$('role').value;for(const [id,value] of [['quickRx','rx'],['quickTx','tx']]){$(id).classList.toggle('selected',role===value);$(id).setAttribute('aria-pressed',String(role===value));}$('quickOrder').textContent=role==='rx'?'ขั้นที่ 1 · เครื่องรับ':'ขั้นที่ 2 · เครื่องส่ง';$('scan').hidden=role==='rx';syncQuickButtons();if(role==='tx')renderScan();}
function chooseQuickRole(role){if(busy||quickLaunching)return;if(started)stop();$('role').value=role;renderQuickRole();$('quickStatus').textContent='';setQuickState('idle',role==='rx'?'เริ่มที่เครื่องรับก่อน':'เครื่องรับพร้อมหรือยัง?',role==='rx'?'กดปุ่มด้านล่าง แล้วอนุญาตไมโครโฟน':'ให้อีกเครื่องกด “เริ่มรับ” ก่อน แล้วกดปุ่มด้านล่าง');$('quickProgress').hidden=true;}
function applyQuickPreset(){setBand({low:20000,high:21000,ms:40});baseline=null;held=null;recommendation=null;peerCapabilities=null;}
function quickError(e){if(e?.name==='NotAllowedError'||e?.name==='PermissionDeniedError')return ['ยังไม่ได้อนุญาตไมโครโฟน','อนุญาตไมโครโฟนให้เว็บ แล้วกดลองอีกครั้ง'];if(e?.name==='NotFoundError'||e?.name==='NotReadableError')return ['เปิดไมโครโฟนไม่ได้','ลองปิดแอพที่ใช้ไมโครโฟน แล้วกดใหม่'];if(/ACK|ช่องควบคุม|ยืนยันการเปลี่ยนย่าน/.test(e?.message||''))return ['ยังติดต่อเครื่องรับไม่ได้','ให้เครื่องรับกด “เริ่มรับ” วางใกล้กัน และลองเพิ่มเสียงเครื่องส่ง'];return ['เริ่มไม่สำเร็จ',e?.message||'กดลองอีกครั้ง'];}
async function quickAction(){if(busy||quickLaunching)return;const role=$('role').value,mine=token;quickLaunching=true;$('quickStatus').textContent='';setQuickState('starting','กำลังเปิดไมโครโฟน','หากมีคำถามจากเบราว์เซอร์ ให้กดอนุญาต');try{applyQuickPreset();await start();if(mine!==token)return;configure();setListen(true);quickLaunching=false;if(role==='rx'){setQuickState('ready','เครื่องรับพร้อมแล้ว','ให้อีกเครื่องเลือก “เครื่องส่ง” แล้วกด “เริ่มทดสอบ”');$('quickStatus').textContent='เปิดหน้านี้ค้างไว้ · กราฟผลจะขึ้นที่เครื่องส่ง';return;}setQuickState('running','กำลังหาเครื่องรับ','ระบบจะไล่ทดสอบย่านเสียงให้เอง');const result=await scanAll();if(mine!==token)return;if(result.complete){setQuickState('complete','ทดสอบเสร็จแล้ว','ดูกราฟและย่านเสียงที่ทำได้ดีที่สุดด้านล่าง');$('quickStatus').textContent='เปลี่ยนเครื่องส่ง–รับเพื่อทดสอบอีกทิศทางได้';}else{const [title,hint]=quickError({message:result.error});setQuickState('error',title,hint);$('quickStatus').textContent='แก้ตามข้อความด้านบน แล้วกด “ลองอีกครั้ง”';}}catch(e){if(mine===token){const [title,hint]=quickError(e);setQuickState('error',title,hint);$('quickStatus').textContent='กด “ลองอีกครั้ง” หลังแก้ไข';}}finally{quickLaunching=false;syncQuickButtons();}}
function reflectQuickStatus(text){if(!quickMode||$('role').value!=='tx'||quickState==='starting')return;if(text.startsWith('ตรวจช่องควบคุม'))setQuickState('running','กำลังหาเครื่องรับ','ให้เครื่องรับเปิดหน้านี้ค้างไว้');const progress=text.match(/ช่วง\s+(\d+)\/(\d+)/),band=text.match(/(\d+\.\d+)–(\d+\.\d+) kHz/);if(progress&&band){setQuickState('running',`กำลังทดสอบช่วง ${progress[1]} จาก ${progress[2]}`,`${band[1]}–${band[2]} kHz · ไม่ต้องกดอะไรเพิ่ม`);}if(text.includes('รอทั้งสองเครื่องกลับ'))setQuickState('running','กำลังเชื่อมต่อใหม่',text.replace('ย่านนี้ตอบกลับไม่ครบ · ',''));}
function refreshQuickProgress(){if($('role').value!=='tx'||!usableScan(scanResult))return;const total=scanResult.bands.length,done=scanResult.bands.filter(b=>b.measurements.length>=scanResult.repeats).length;$('quickProgress').hidden=false;$('quickProgressBar').value=done/total*100;$('quickProgressLabel').textContent=`ทดสอบแล้ว ${done} / ${total} ช่วง`;}
bind('quickRx',()=>chooseQuickRole('rx'));bind('quickTx',()=>chooseQuickRole('tx'));bind('quickStart',quickAction);renderQuickRole();
